function createSortingVisualizer(canvasId) {
  const canvas = document.getElementById(canvasId);
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.height = 500;

  // UI Elements
  const container = document.createElement('div');
  container.style.position = 'relative';
  container.style.width = container.style.height = '500px';
  container.appendChild(canvas);

  const controls = document.createElement('div');
  controls.style.position = 'absolute'; controls.style.top = '10px'; controls.style.left = '10px';
  controls.style.background = 'rgba(255,255,255,0.8)'; controls.style.padding = '10px'; controls.style.borderRadius = '4px';
  container.appendChild(controls);

  const algoSelect = document.createElement('select');
  ['Bubble', 'Quick', 'Merge', 'Heap', 'Radix'].forEach(a=>{
    const opt = document.createElement('option'); opt.value = a; opt.text = a; algoSelect.appendChild(opt);
  });
  controls.appendChild(algoSelect);

  const startBtn = document.createElement('button'); startBtn.textContent = 'Start'; controls.appendChild(startBtn);
  const stepBtn =.createElement('button'); stepBtn.textContent = 'Step'; stepBtn.disabled = true; controls.appendChild(stepBtn);
  const continuousChk = document.createElement('input'); continuousChk.type 'checkbox'; continuousChk.id = 'cont';
  const continuousLbl = document.createElement('label'); continuousLbl.htmlFor = 'cont'; continuousLbl.textContent = 'Continuous';
  controls.appendChild(continuousChk); controls.appendChild(continuousLbl);

  const speedRange = document.createElement('input'); speedRange.type = 'range'; speedRange.min = '1'; speedRange.max = '60'; speedRange.value = '20'; speedRange.style.width = '100px';
  controls.appendChild(document.createTextNode('Speed: '));
  controls.appendChild(speedRange);

  const scrambleSelect = document.createElement('select');
  ['Random', 'Reverse', 'Nearly Sorted'].forEach(p=>{
    const opt = document.createElement('option'); opt.value = p; opt.text = p; scrambleSelect.appendChild(opt);
  });
  controls.appendChild(document.createTextNode(' Scramble: '));
  controls.appendChild(scrambleSelect);

  const info = document.createElement('div'); info.style.marginTop = '10px';
  const oNotation = document.createElement('div');
  const comCount = document.createElement('div');
  const swapCount = document.createElement('div');
  const depthInfo = document.createElement('div');
  const workingInfo = document.createElement('div');
  info.appendChild(oNotation); info.appendChild(comCount); info.appendChild(swapCount);
  info.appendChild(depthInfo); info.appendChild(workingInfo);
  controls.appendChild(info);

  document.body.appendChild(container);

  const BAR_COUNT = 80;
  const BAR_WIDTH = canvas.width / BAR_COUNT;
  let data = Array.from({length: BAR_COUNT}, (_,i)=>i+1);
  let sorted = new Set();
  let comparisons = 0, swaps = 0, maxDepth = 0, currentDepth = 0, workingRange = null;
  let gen = null;
  let lastTime = 0, delay = 1000/parseInt(speedRange.value);
  let running = false;

  function resetStats() {
    sorted.clear(); comparisons=0; swaps=0; maxDepth=0; currentDepth=0; workingRange=null;
  }

  function scramble(pattern='Random') {
    resetStats();
    if (pattern==='Random'){
      for(let i=data.length-1;i>0;i--) {
        const j=Math.floor(Math.random()*(i+1));
        [data[i],data[j]]=[data[j],data[i]];
      }
    }else if(pattern==='Reverse'){
      data=data.slice().reverse();
    }else if(pattern==='Nearly Sorted'){
      for(let i=0;i<data.length;i+=5){
        if(i+1<data.length){
          [data[i],data[i+1]]=[data[i+1],data[i]];
        }
      }
    }
  }

  scramble('Random');

  function render() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for(let i=0;i<BAR_COUNT;i++){
      const val = data[i];
      let col='#555';
      if(colored[i]) col=colored[i];
      const height = val*canvas.height/BAR_COUNT;
      ctx.fillStyle = col;
      ctx.fillRect(i*BAR_WIDTH, canvas.height-height, BAR_WIDTH-1, height);
    }
    if(workingRange){
      ctx.fillStyle = 'rgba(0,128,255,0.3)';
      ctx.fillRect(workingRange.start*BAR_WIDTH, 0, (workingRange.end-workingRange.start+1)*BAR_WIDTH, canvas.height);
    }
  }

  const colored = Array(BAR_COUNT).fill('#555');

  // Generators for algorithms
  function* bubbleSort(arr){
    const n=arr.length;
    for(let i=0;i<n-1;i++){
      for(let j=0;j<n-i-1;j++){
        colored[j]=colored[j+1]='red';
        yield;
        comparisons++;
        if(arr[j]>arr[j+1]){
          [arr[j],arr[j+1]]=[arr[j+1],arr[j]];
          colored[j]=colored[j+1]='yellow';
          yield;
          swaps++;
        }
        colored[j]=colored[j+1]='#555';
      }
      colored[n-i-1]='green';
      sorted.add(n-i-1);
      yield;
    }
    for(let i=0;i<n;i++){
      colored[i]='green';
      sorted.add(i);
      yield;
    }
  }

  function* quickSort(arr){
    const stack=[{low:0, high:arr.length-1, depth:0}];
    while(stack.length){
      const {low, high, depth}=stack.pop();
      currentDepth=depth;
      if(low<high){
        const pi=partition(low,high,depth);
        stack.push({low:pi+1, high:high, depth:depth+1});
        stack.push({low:low, high:pi-1, depth:depth+1});
      }
    }
    for(let i=0;i<arr.length;i++){
      colored[i]='green'; sorted.add(i); yield;
    }

    function partition(low,high,depth){
      const pivot=arr[high];
      colored[high]='blue';
      yield;
      let i=low-1;
      for(let j=low;j<high;j++){
        colored[j]=colored[high]='red';
        yield; comparisons++;
        if(arr[j]<=pivot){
          i++;
          if(i!==j){
            [arr[i],arr[j]]=[arr[j],arr[i]];
            colored[i]=colored[j]='yellow';
            yield; swaps++;
          }
        }
        colored[j]=colored[high]='#555';
      }
      if(i+1!==high){
        [arr[i+1],arr[high]]=[arr[high],arr[i+1]];
        colored[i+1]=colored[high]='yellow';
        yield; swaps++;
      }
      colored[high]='#555';
      return i+1;
    }
  }

  function* mergeSort(arr){
    function* mergeSortRec(arr, l, r, depth){
      if(l<r){
        const m=Math.floor((l+r)/2);
        workingRange={start:l, end:r, depth};
        yield* mergeSortRec(arr,l,m,depth+1);
        yield* mergeSortRec(arr,m+1,r,depth+1);
        const left=arr.slice(l,m+1);
        const right=arr.slice(m+1,r+1);
        let i=0,j=0,k=l;
        while(i<left.length && j<right.length){
          colored[k]='red';
          yield; comparisons++;
          if(left[i]<=right[j]){
            arr[k]=left[i++]; colored[k]='yellow'; yield; swaps++; 
          }else{
            arr[k]=right[j++]; colored[k]='yellow'; yield; swaps++;
          }
          colored[k]='#555'; k++;
        }
        while(i<left.length){arr[k++]=left[i++]; colored[k-1]='green'; yield;}
        while(j<right.length){arr[k++]=right[j++]; colored[k-1]='green'; yield;}
        workingRange=null;
      }
    }
    yield* mergeSortRec(arr,0,arr.length-1,0);
    for(let i=0;i<arr.length;i++){colored[i]='green'; sorted.add(i); yield;}
  }

  function* heapSort(arr){
    const n=arr.length;
    for(let i=Math.floor(n/2)-1;i>=0;i--) yield* heapify(n,i);
    for(let i=n-1;i>=0;i--){
      [arr[0],arr[i]]=[arr[i],arr[0]];
      colored[0]=colored[i]='yellow'; yield; swaps++;
      colored[0]='#555'; colored[i]='green'; sorted.add(i); yield;
      yield* heapify(i,0);
    }

    function* heapify(n,i){
      let largest=i;
      const l=2*i+1, r=2*i+2;
      if(l<n && arr[l]>arr[largest]) largest=l;
      if(r<n && arr[r]>arr[largest]) largest=r;
      if(largest!==i){
        [arr[i],arr[largest]]=[arr[largest],arr[i]];
        colored[i]=colored[largest]='yellow'; yield; swaps++;
        yield* heapify(n,largest);
      }
    }
  }

  function* radixSort(arr){
    const max=Math.max(...arr);
    let exp=1;
    while(Math.floor(max/exp)>0){
      const output=Array(arr.length).fill(0);
      const count=Array(10).fill(0);
      for(let i=0;i<arr.length;i++){
        const index=Math.floor(arr[i]/exp)%10;
        count[index]++; colored[i]='red'; yield; comparisons++;
        colored[i]='#555';
      }
      for(let i=1;i<10;i++) count[i]+=count[i-1];
      for(let i=arr.length-1;i>=0;i--){
        const index=Math.floor(arr[i]/exp)%10;
        output[--count[index]]=arr[i];
        colored[i]='yellow'; yield; swaps++;
        colored[i]='#555';
      }
      for(let i=0;i<arr.length;i++) arr[i]=output[i];
      exp*=10;
    }
    for(let i=0;i<arr.length;i++){colored[i]='green'; sorted.add(i); yield;}
  }

  const generators = {
    'Bubble': bubbleSort,
    'Quick': quickSort,
    'Merge': mergeSort,
    'Heap': heapSort,
    'Radix': radixSort
  };

  const oMap = {
    'Bubble': 'O(n²)',
    'Quick': 'O(n log n)',
    'Merge': 'O(n log n)',
    'Heap': 'O(n log n)',
    'Radix': 'O(nk)'
  };

  function startAlgo(){
    resetStats();
    scramble(scrambleSelect.value);
    running = false;
    generator = generators[algoSelect.value](data);
    oNotation.textContent = `Complexity: ${oMap[algoSelect.value]}`;
    stepBtn.disabled = continuousChk.checked;
    animate();
  }

  function animate(){
    const now = performance.now();
    if(now - lastTime < delay) requestAnimationFrame(animate);
    else{
      lastTime = now;
      const result = generator.next();
      if(result.done){
        running=false; stepBtn.disabled=true; return;
      }
      updateInfo();
      render();
      requestAnimationFrame(animate);
    }
  }

  function updateInfo(){
    oNotation.textContent = `Complexity: ${oMap[algoSelect.value]}`;
    comCount.textContent = `Comparisons: ${comparisons}`;
    swapCount.textContent = `Swaps: ${swaps}`;
    depthInfo.textContent = `Call Stack Depth: ${currentDepth}`;
    workingInfo.textContent = workingRange ? `Working Range: ${workingRange.start}-${workingRange.end}` : '';
  }

  startBtn.onclick = startAlgo;
  stepBtn.onclick = ()=>{
    if(generator){
      const res = generator.next();
      if(res.done) stepBtn.disabled=true;
      updateInfo();
      render();
    }
  };
  continuousChk.onchange = ()=>{
    stepBtn.disabled = continuousChk.checked;
  };
  speedRange.oninput = ()=>{
    delay = 1000/parseInt(speedRange.value);
  };
  scrambleSelect.onchange = ()=>{
    scramble(scrambleSelect.value);
    render();
  };

  render();
}
